local M = class("DoubleFestivalMainView",LikeOO.OOPopBase)

M.m_uiName = "DoubleFestivalActivity/DoubleFestivalMain"  -- prefab name
M.m_size_type = 1
M.m_iphoneXAdapter = true

local __NameFormat = {
    TabName = "text_tabName_",
    RedName = "img_redDot_",
    BtnName = "btn_togglebtn_",
    ShowTabName = "showTagIndex_",
}

function M:onEnter()
    EventDispatcher:registerEvent(GlobalConfig.EVENT_KEYS.EVERY_DAY_EVENT, {self, self.everyDayRefreshEvent})
    self.m_control:setShowTreeEnterEvent()
    self.m_content_panel = self:findGameObject("parentNode")
    self.grayImage = self:findImage("grayImage")
    self.tabImg_2 = self:findImage("btn_togglebtn_2") 
    
    for _, itemData in pairs(self.m_model.m_tab_Node) do
        local index = itemData.index
        if index > 0 then
            local btn_text = __NameFormat.TabName .. index
            local itemActivityXlsxData = self.m_model.m_activityXlsxData[itemData.open_id] or {}
            local titleName = itemActivityXlsxData.name or ""
            self:setTextByLanKey(btn_text, Language:getTextByKey(titleName))
            --UIUtil.addToggleListener(tog_btn, function(is_on) self:switchTabUpdate(is_on, index) end,nil,self.m_uiName)
            self:setObjectVisible(__NameFormat.RedName..index, false)
        end
    end

    local showTypeIndex = self.m_model.m_jumpIndex
    if not self.m_model:isOpenStatusByOpenId(showTypeIndex) then
        showTypeIndex = 3
    end
    self:switchTabUpdate(showTypeIndex)
    self:bindUI()
end

function M:refreshTab2Type()
    --local cost = ConfigManager:getCommonValueById(610) or 0
    self.tabImg_2.material = (self.m_model.m_isShowTree == false) and self.grayImage.material or nil
end

function M:everyDayRefreshEvent()
    self.m_control:refreshChildView(true, false)
    self.m_model:setCurDay(self.m_model:getCurDay())
end

function M:switchTabUpdate(index)
    if index ~= self.m_model.m_open_tab_index then
        if (index == 2) and (not self.m_model.m_isShowTree) then
            local curServerTimer = UserDataManager:getServerTime()
            local targetTimer = ConfigManager:getCommonValueById(611) or curServerTimer
            local residueTimer = targetTimer - curServerTimer
            residueTimer = residueTimer > 0 and residueTimer or 0
            local targetT = GameUtil:formatTimeBySecond(residueTimer, 999)
            GameUtil:lookInfoTips(self.m_control, {msg = Language:getTextByKey("doubleFestival_text_0035",targetT), delay_close = 2})
        else
            if self.m_model:isOpenStatusByOpenId(index) or index == 3 then
                self:setObjectVisible(__NameFormat.ShowTabName..self.m_model.m_open_tab_index, false)
                self:updateMsg(index)
            else
                GameUtil:lookInfoTips(self.m_control, {msg = Language:getTextByKey("gf_str_0085"), delay_close = 2})
            end
        end
    end
end


function M:switchTabNode(isDeleteViewNode)
    -- 红点
    local curTimer = UserDataManager:getServerTime()
    local m_activityDatas = self.m_model.m_activityDatas or {}
    for openId, activityItemData in pairs(self.m_model.m_serverDatas) do
        local redDotIndex = activityItemData.itemData.index
        local curActivityData = m_activityDatas[openId]
        local isShowRedDot = activityItemData.isShowRedDot
        if isShowRedDot and (redDotIndex ~= 3) then
            isShowRedDot = (curTimer < curActivityData.show_start_ts )
        end
        if isShowRedDot and (redDotIndex == 4) then
            isShowRedDot = self:isShowTabBtn4()
        end
        self:setObjectVisible(__NameFormat.RedName..redDotIndex, isShowRedDot)
    end

    if isDeleteViewNode then
        if self.m_cur_tab_node then
            self.m_cur_tab_node:destroy()
            self.m_cur_tab_node = nil
        end
    end
    
    local selectIndex = self.m_model.m_open_tab_index
    for _, itemData in pairs(self.m_model.m_tab_Node) do
        -- tab字体
        local index = itemData.index
        if index > 0 then
            local isSelectIndex = (index == selectIndex)
            local btn_text = __NameFormat.TabName .. index
            local cur_tab_text = self:findText(btn_text)
            cur_tab_text.color = isSelectIndex and Color( 143/255, 62/255, 36/255) or  Color( 31/255, 34/255, 45/255)

            -- 切换界面
            if isSelectIndex then
                if isDeleteViewNode then
                    if itemData.lua_name then
                        local tab_cls = CustomRequire(itemData.lua_name)
                        self.m_cur_tab_node = tab_cls.new(self.m_control, {parent = self.m_content_panel})
                    end
                else
                    if self.m_cur_tab_node then
                        self.m_cur_tab_node:refreshUI()
                    end
                end
            end
        end
    end
    self:setObjectVisible(__NameFormat.ShowTabName..selectIndex, true)

    self:refreshTab2Type()
end

function M:bindUI()
    local mainData = self.m_model.m_activityXlsxData[self.m_model.m_mainOpenId]
    local titleName = mainData.name
    self:setTextByLanKey("close_title_text", titleName)
    
    self:setObjectVisible("tabNode4", self:isShowTabBtn4())
    self:refreshAllRedDot()
end

-- 是否显示第四个按钮
function M:isShowTabBtn4()
    local curStage = UserDataManager:getCurStage()
    local tempActivity = ConfigManager:getCfgByName("active_recharge")
    local targetStage = nil
    for _, itemData in pairs(tempActivity) do
        if itemData.open_id == 230 then
            targetStage = itemData.stage_id
        end
    end
    return ( curStage >= targetStage)
end

function M:refreshAllRedDot()
   
end

function M:destroy()
    EventDispatcher:unRegisterEvent(GlobalConfig.EVENT_KEYS.EVERY_DAY_EVENT, {self, self.everyDayRefreshEvent})
    self.m_control:updateMsg("common_refresh", nil, "parent")
    if self.m_cur_tab_node then
        self.m_cur_tab_node:destroy()
        self.m_cur_tab_node = nil
    end
    M.super.destroy(self)
end

return M